messageValues.message:
Eres el asistente inteligente de la biblioteca escolar de Tuxtla Gutiérrez. Analiza el mensaje del estudiante y extrae la intención y parámetros en formato JSON estricto (únicamente el objeto JSON):

{
  "intencion": "buscar_libro" | "consultar_prestamos" | "renovar_prestamo" | "vincular_estudiante" | "general",
  "query_busqueda": "término, libro o autor a buscar",
  "titulo_libro_renovar": "título del libro que desea renovar",
  "student_code": "matrícula escolar si desea vincularse (ej. EST-202401)",
  "respuesta_amable": "respuesta conversacional si solo saludó o hizo una pregunta general"
}

Ejemplos:
- "¿Tienen libros de cálculo de James Stewart?" -> {"intencion": "buscar_libro", "query_busqueda": "calculo stewart"}
- "mis préstamos" o "¿cuándo vencen mis libros?" o "¿tengo multas?" -> {"intencion": "consultar_prestamos"}
- "renovar cálculo" o "extender mi libro de álgebra" -> {"intencion": "renovar_prestamo", "titulo_libro_renovar": "cálculo"}
- "mi matrícula es EST-202401" o "vincular EST-202401" -> {"intencion": "vincular_estudiante", "student_code": "EST-202401"}
- "hola, buenos días" -> {"intencion": "general", "respuesta_amable": "¡Hola! ¿En qué puedo ayudarte hoy con la biblioteca escolar?"}

parameters.jsCode:
const trigger = $('Telegram Trigger').first().json.message;
const text = trigger.text || '';
const lower = text.toLowerCase().trim();
const chatId = trigger.chat.id;

let parsed = {
  chatId: chatId,
  originalText: text,
  intencion: 'general',
  query_busqueda: '',
  titulo_libro_renovar: '',
  student_code: '',
  respuesta_amable: ''
};

// 1. Procesar respuesta del modelo de IA si existe
let aiOutput = $json.text || $json.output || '';
if (typeof aiOutput === 'string' && aiOutput.includes('{')) {
  try {
    const clean = aiOutput.replace(/```json/g, '').replace(/```/g, '').trim();
    const aiJson = JSON.parse(clean);
    if (aiJson.intencion) parsed.intencion = aiJson.intencion;
    if (aiJson.query_busqueda) parsed.query_busqueda = aiJson.query_busqueda;
    if (aiJson.titulo_libro_renovar) parsed.titulo_libro_renovar = aiJson.titulo_libro_renovar;
    if (aiJson.student_code) parsed.student_code = aiJson.student_code;
    if (aiJson.respuesta_amable) parsed.respuesta_amable = aiJson.respuesta_amable;
  } catch (e) {}
}

// 2. Capa de respaldo inteligente (Reglas y Comandos directos)
const matriculaMatch = text.match(/EST[-\s]?\d+/i) || text.match(/vincular\s+([A-Za-z0-9-_]+)/i);

if (matriculaMatch || lower.startsWith('/vincular') || lower.includes('matrícula') || lower.includes('matricula')) {
  parsed.intencion = 'vincular_estudiante';
  parsed.student_code = matriculaMatch ? matriculaMatch[0].toUpperCase().replace(/\s/g, '-') : text.replace(/\/vincular/i, '').replace(/vincular/i, '').trim();
} else if (lower === '/mis_prestamos' || lower.includes('prestam') || lower.includes('venc') || lower.includes('multa') || lower.includes('mis libros')) {
  parsed.intencion = 'consultar_prestamos';
} else if (lower.includes('renov') || lower.includes('extender') || lower.includes('prórroga') || lower.includes('prorroga')) {
  parsed.intencion = 'renovar_prestamo';
  parsed.titulo_libro_renovar = parsed.titulo_libro_renovar || text.replace(/renovar/i, '').replace(/libro/i, '').replace(/mi/i, '').trim();
} else if (lower.includes('buscar') || lower.includes('libro') || lower.includes('tienen') || lower.includes('hay') || lower.includes('disponible') || lower.includes('stewart') || lower.includes('calculo') || lower.includes('fisica') || lower.includes('algebra')) {
  parsed.intencion = 'buscar_libro';
  parsed.query_busqueda = parsed.query_busqueda || text.replace(/tienen/i, '').replace(/libros/i, '').replace(/libro/i, '').replace(/de/i, '').replace(/buscar/i, '').trim();
} else if (lower === '/start' || lower === '/ayuda' || lower.includes('hola') || lower.includes('buenos') || lower.includes('buenas')) {
  parsed.intencion = 'general';
  parsed.respuesta_amable = `👋 ¡Hola ${trigger.from.first_name || ''}! Soy el asistente virtual de la biblioteca escolar de Tuxtla Gutiérrez. 📚\n\nPuedes pedirme en cualquier momento:\n🔍 *Buscar libros*: "¿Tienen libros de cálculo de Stewart?"\n📋 *Ver tus préstamos*: "¿Cuándo vencen mis libros?" o /mis_prestamos\n🔄 *Renovar libros*: "Renovar mi libro de física"\n🔗 *Vincularte*: "Mi matrícula es EST-202401"`;
}

return parsed;

parameters.text:
={{
  (() => {
    const d = $json.data;
    if (!d || !d.registered) return '⚠️ Tu cuenta de Telegram aún no está vinculada.\n\nEscribe: "Mi matrícula es EST-202401" para asociar tu cuenta.';
    if (!d.loans || d.loans.length === 0) return '📋 Estado de tus Préstamos (' + d.student.name + '):\n\nNo tienes libros prestados actualmente.';
    let msg = '📋 Estado de tus Préstamos (' + d.student.name + '):\n\n';
    for (const l of d.loans) {
      msg += '📖 ' + l.bookTitle + '\n🗓️ Vence: ' + l.dueDate + ' (' + l.status + ')\n🔄 Renovaciones: ' + l.renewalsMade + '/' + l.maxRenewals + '\n\n';
    }
    if (d.student.hasPenalty) {
      msg += '⚠️ Tienes una multa pendiente de $' + d.student.penaltyAmount + ' MXN';
    }
    return msg;
  })()
}}

={{
  (() => {
    const d = $json.data;
    if (d && d.success) {
      return '🔄 ' + d.message + '\n🗓️ Nueva entrega: ' + d.newDueDate;
    }
    return '⚠️ ' + (d && d.message ? d.message : ($json.message || 'No fue posible renovar el préstamo.'));
  })()
}}

={{
  (() => {
    const d = $json.data;
    if (!d || !d.books || d.books.length === 0) return '📚 No encontramos libros con ese término en el acervo. Intenta con otro autor o título.';
    let msg = '📚 Libros Encontrados (' + d.totalFound + '):\n\n';
    for (const b of d.books) {
      msg += '📖 ' + b.title + '\n✍️ Autor: ' + b.author + '\n📍 Estante: ' + b.locationShelf + '\n📂 ' + b.statusText;
      if (b.isDigital && b.digitalUrl) {
        msg += '\n🔗 Digital: ' + b.digitalUrl;
      }
      msg += '\n\n---\n\n';
    }
    return msg;
  })()
}}

={{
  (() => {
    const d = $json.data;
    if (d && d.success) {
      return '🎉 ' + d.message + '\n\nYa puedes consultar tus préstamos activos enviando /mis_prestamos.';
    }
    return '⚠️ ' + (d && d.message ? d.message : ($json.message || 'No se pudo realizar la vinculación.'));
  })()
}}
